*******************************************************************************			                 ** This Init program	causes tool033 to startup which causes it to perform its ** time consuming presence test for the Video Overlay Card.	We need this     ** to be done in an init program because	it turns interrupts	off for a  long  ** period of time which in turn can cause time crucial interrupt code not to  ** service interrupts in time (usually a	loss of data.)	                 **			                 **	    Version 1.0 -- April 1989	                 **			                 *******************************************************************************	INCLUDE 'all.macros'******************************************************************  The main program*****************************************************************	EXPORT VDINITVDINIT	PROC;----------------------------------------------------;; Set the data bank	to code bank so I can use absolute; addressing.;	phb	;save data bank	phk	;get programs data bank	plb	;set data bank to program bank;-----------------------------------------------;; Start with TLStartup;	_TLStartup	; Tool Locator;-------------------------------------------------;; Initialize the memory manager.;	PushWord #0	_MMStartup	pla	sta MyID;-------------------------------------------------;; Now see if the tool is already there (dont do anything if	it is);	PushWord #0	;space for result	ldx #$0621	;vdstatus	jsl $e10000	;perform vdstatus	bcs NotThere	;branch if not there	pla	;get result off stack;We arrive here if the tool is already there, don't load it	bra OutOfHere;We arrive here if the tool isn't there, load it upNotThere		; 	pla	;get result off stack	PushWord #33	;load tool033	PushWord #0	;min. version of 0	_LoadOneTool	bcs OutOfHere	;do nothing is cant	load tool;Now start it up (cause presence test to occur and send message)	ldx #$0221	;vdstartup	jsl $e10000	;perform vdstartup	ldx #$0321	;vdshutdown	jsl $e10000	;perform vdshutdown;Because we loaded it, unload it	PushWord #33	;tool033	_UnLoadOneTool	;unload the tool;-------------------------------------------------;; Now shut everything down;OutOfHere		; 	PushWord MyID	_MMShutdown	_TLShutdown	plb	;restore bank	rtl	;because inits end this wayMyId	DS.B 2	;my memory manager ID	ENDP	END